# 注意：2/0/0 与 2/0/1 各含坐标，主代理也读了；其余瓦片坐标见各自JSON文件。
# 本脚本统计 height/floors 不依赖坐标，去重靠 uuid_bgn。

# 合并去重
by_uuid = {}
raw_records = 0
for uri, t in TILES.items():
    n = len(t["uuid_bgn"])
    raw_records += n
    for i in range(n):
        u = t["uuid_bgn"][i]
        rec = {
            "uuid": u,
            "height": t["building_height"][i],
            "floors": t["number_of_floors"][i],
            "owner": t["owner_name"][i],
            "first_tile": uri,
        }
        if u not in by_uuid:
            by_uuid[u] = rec

uniq = list(by_uuid.values())
N = len(uniq)

def cnt_h(thr): return sum(1 for r in uniq if r["height"] >= thr)
def cnt_f(thr): return sum(1 for r in uniq if r["floors"] >= thr)

stats = {
    "tiles_parsed": len(TILES),
    "raw_records": raw_records,
    "unique_buildings": N,
    "dup_removed": raw_records - N,
    "height_ge_32m": cnt_h(32),
    "height_ge_40m": cnt_h(40),
    "height_ge_48m": cnt_h(48),
    "floors_ge_8": cnt_f(8),
    "floors_ge_10": cnt_f(10),
    "floors_ge_12": cnt_f(12),
    "height_max": max(r["height"] for r in uniq),
    "height_min": min(r["height"] for r in uniq),
}

top = sorted(uniq, key=lambda r: r["height"], reverse=True)[:15]

# 输出
with open(os.path.join(DATA_DIR, "surabaya_3d_lod2_buildings_all.json"), "w", encoding="utf-8") as f:
    json.dump({"stats": stats, "buildings": uniq}, f, ensure_ascii=False, indent=1)

print(json.dumps(stats, ensure_ascii=False, indent=2))
print("\nTOP 15:")
for r in top:
    print(f"  {r['height']:>7.3f} m  {r['floors']:>2} 层  {r['owner']:<30} {r['uuid'][:8]} [{r['first_tile']}]")
